parameters.jsCode:
const b = $input.item.json.body || $input.item.json;
const nip = b.nip || $input.item.json.headers?.['x-nip'] || 'ADMIN';
const jumlah = Number(b.jumlah);
// Bentuk modern (barang_id + jenis) dipakai route native /api/simapo/mutasi-save,
// bentuk lama (barangmasukid / barangkeluarid) dipakai pemanggil webhook lama.
// Sebelum normalisasi ini, payload modern menghasilkan barangid null dan delta
// selalu negatif, jadi mutasi MASUK ikut tercatat sebagai KELUAR.
// Urutan penting: pemanggil legacy yang mengirim barangkeluarid tetap KELUAR.
const S = (v) => (v === undefined || v === null ? '' : String(v).trim());
const legacyMasuk = S(b.barangmasukid) || null;
const legacyKeluar = S(b.barangkeluarid) || null;
const barangId = S(b.barang_id) || S(b.barangid) || legacyMasuk || legacyKeluar || null;
const isMasuk = legacyMasuk ? true
  : legacyKeluar ? false
  : b.jenis ? String(b.jenis).toUpperCase() === 'MASUK' : true;
// Default MASUK saat jenis kosong, sama dengan route native simapo.js:537.
const masId = isMasuk ? barangId : null;
const kelId = isMasuk ? null : barangId;
const delta = isMasuk ? jumlah : -jumlah;
const barangid = barangId;

// Guard yang sama dengan route native (server/simapo.js:531-562). Tanpa ini,
// payload tanpa id tetap menulis baris mutasi yang barangnya tidak pernah
// berubah stoknya, dan jumlah 0 tersimpan sebagai mutasi sungguhan. Melempar
// di node ini menghentikan eksekusi sebelum node PG, jadi tidak ada sisa yang
// perlu dibersihkan.
if (!barangId) throw new Error('barang_id wajib diisi.');
if (!Number.isInteger(jumlah) || jumlah < 1) throw new Error('jumlah harus bilangan bulat >= 1.');

return [{ json: {
  barangmasukid: masId,
  barangkeluarid: kelId,
  barangid: barangid,
  createdbyid: nip,
  jumlah: jumlah,
  delta: delta,
  keterangan: b.keterangan || '',
  tanggal: new Date().toISOString(),
  instansi_id: b.instansi_id || $input.item.json.query?.instansi_id || 'bapperida'
} }];

parameters.query:
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "SIMAPO".barang
     WHERE id = '{{ ($json.barangid).toString().replace(/'/g, "''") }}'
       AND instansi_id = '{{ ($json.instansi_id || "bapperida").toString().replace(/'/g, "''") }}'
       AND isactive
  ) THEN
    RAISE EXCEPTION 'barang tidak ditemukan atau bukan milik instansi ini';
  END IF;
END $$;
INSERT INTO "SIMAPO".mutasi_barang (id, barangmasukid, barangkeluarid, createdbyid, jumlah, keterangan, tanggal, instansi_id) VALUES (gen_random_uuid(), {{ ($json.barangmasukid ? "'" + $json.barangmasukid + "'" : 'NULL').toString().replace(/'/g, "''") }}, {{ ($json.barangkeluarid ? "'" + $json.barangkeluarid + "'" : 'NULL').toString().replace(/'/g, "''") }}, '{{ ($json.createdbyid).toString().replace(/'/g, "''") }}', {{ ($json.jumlah).toString().replace(/'/g, "''") }}, '{{ ($json.keterangan).toString().replace(/'/g, "''") }}', '{{ ($json.tanggal).toString().replace(/'/g, "''") }}', '{{ ($json.instansi_id || "bapperida").toString().replace(/'/g, "''") }}'); UPDATE "SIMAPO".barang SET stok_saat_ini = GREATEST(0, stok_saat_ini + ({{ ($json.delta).toString().replace(/'/g, "''") }})), updatedat = NOW() WHERE id = '{{ ($json.barangid).toString().replace(/'/g, "''") }}'
  AND instansi_id = '{{ ($json.instansi_id || "bapperida").toString().replace(/'/g, "''") }}'
  AND isactive RETURNING id, stok_saat_ini;

SELECT COALESCE(json_agg(t.*), '[]'::json) as items FROM (
SELECT m.id, b.nama AS nama_barang, b.kodebarang, m.jumlah, m.keterangan, m.createdbyid, COALESCE(u."username", m.createdbyid) AS nama_petugas, TO_CHAR(m.tanggal,'YYYY-MM-DD HH24:MI') AS createdat, CASE WHEN m.barangmasukid IS NOT NULL THEN 'MASUK' ELSE 'KELUAR' END as jenis FROM "SIMAPO".mutasi_barang m LEFT JOIN "SIMAPO".barang b ON b.id = COALESCE(m.barangmasukid, m.barangkeluarid) LEFT JOIN public.user_list u ON u."NIP" = m.createdbyid WHERE m.instansi_id = '{{ ($json.query.instansi_id || 'bapperida').toString().replace(/'/g, "''") }}' ORDER BY m.tanggal DESC LIMIT 50
) t;
